def connection_closed_handler(function):
    """Handle AdminApiConnectionClosedException."""
    @wraps(function)
    def _wrap(inst, *args, **kwargs):
        try:
            return function(inst, *args, **kwargs)

        except (AdminApiConnectionClosedException, WebSocketConnectionClosedException) as e:
            inst.logger.debug("{}: {}".format(type(e), e))
            inst.logger.warning("Admin API connection lost. Resetting ...")
            inst.logger.info("reset timeout: {}".format(str(args[1])))
            inst.logger.info("procedure timeout: {}".format(str(kwargs.get("timeout"))))
            inst.reset(args[1])
            return function(inst, *args, **kwargs)
    return _wrap


class AdminBaseApi(metaclass=ABCMeta):

    def __init__(self, timeout):
        self.timeout = timeout
        self.ws = None
        self.web_socket_app_should_work = True
        self.msg_queue = queue.Queue()
        self.last_matching_response = None
        self.logger = AdminApiLogger()
        self.message_flow_logger = logging.getLogger("taf.internal.sbts.admin.cli.AdminBaseApi")
        self.message_flow_logger.addHandler(logging.NullHandler())
        self.message_flow_logger.propagate = False

    def enable_trimming(self):
        self.logger.enable_trimming(max_length=60)

    def setup(self):
        """Setup Admin API"""
        self.look_for_open_node_process()
        self.process.logger.info("taf.internal.sbts.admin.cli version: {}".format(get_library_version("taf.internal.sbts.admin.cli")))
        self.process.logger.info("taf.sbts.oam.coam.admin version: {}".format(get_library_version("taf.sbts.oam.coam.admin")))
        self.process.logger.debug("taf host memory before Admin CLI start: {}".format(str(get_memory_usage())))
        self.process.start()
        self.ws_thread = Thread(target=self._run_websocket, daemon=True)
        self.ws_thread.start()
        if not self.process.remote_host:
            self.process.logger.debug("Admin CLI pid: {}".format(self.process.process.pid))
            self._log_process_info()
            self.look_for_open_node_process()
            self.process.logger.debug(
                "taf host memory after Admin CLI start: {}".format(str(get_memory_usage())))
        self._wait_for_ws_connection(self.timeout)

    def teardown(self):
        """Teardown Admin API"""
        if not self.process.remote_host:
            self._log_process_info()
        self.process.stop()
        self.web_socket_app_should_work = False
        if self.ws:
            self.ws.close()
        else:
            self.logger.warning("WebSocket thread not found")
        if hasattr(self, "ws_thread"):
            self.ws_thread.join(2)
        else:
            self.logger.warning("WebSocket thread could not be closed")

    def reset(self, timeout=None):
        """Reset Admin API"""
        self.process.restart(10 if not timeout else timeout)
        self._wait_for_ws_connection(self.timeout if not timeout else timeout)
        self._clear_msg_queue()

    def look_for_open_node_process(self):
        """Looks for opened processes"""

    @abstractmethod
    def execute_infomodel_request(self, name, parameters, timeout):
        """Execute AdminAPI InfoModel request."""

    @abstractmethod
    def execute_procedure(self, name, parameters, timeout):
        """Execute AdminAPI procedure."""

    @connection_closed_handler
    def execute_request(self, request, timeout, detailed_output=False):
        """Execute AdminAPI request."""
        if self.process.forwarder:
            self.logger.debug("sshForwarder is active: {}".format(self.process.forwarder.is_active))
            try:
                self.logger.debug("local bind port: {}".format(self.process.forwarder.local_bind_ports))
            except Exception as e:
                self.logger.debug("execute_request {}: {}".format(type(e), e))
                raise AdminApiConnectionClosedException("execute_request {}: {}".format(type(e), e))

        self._send_message(request)
        response = self._wait_until_completed(request, timeout)
        if response.is_success():
            return response.get_payload(detailed=True) if detailed_output else response.get_payload()
        elif response.is_failure():
            raise AdminApiProcedureFailureException("""Response for request ID {}, type {}: {}
            Status reached: {}. ErrorCode: {}""".format(request.requestId, request.requestType, request.parameters,
                                                        response.get_payload(), response.errorCode), error_code=response.errorCode)
        else:
            raise AdminApiProcedureTimeoutException(""""Request ID {}, type {}: {}
            not completed within timeout: {} sec. Status reached: {}""".format(request.requestId,
                                                                               request.requestType,
                                                                               request.parameters,
                                                                               timeout,
                                                                               response.get_payload()))

    def _clear_msg_queue(self):
        with self.msg_queue.mutex:
            self.msg_queue.queue.clear()

    def _run_websocket(self):
        while self.web_socket_app_should_work:
            self.ws = WebSocketApp(self.process.get_url(),
                                   on_open=self._on_open,
                                   on_message=self._on_message,
                                   on_close=self._on_close,
                                   on_error=self._on_error)
            self.ws.run_forever(skip_utf8_validation=True)
            sleep(2)

    def _on_open(self, ws):
        self.msg_queue.put(messages.ConnectionOpen())

    def _on_close(self, ws, close_status_code, close_msg):
        self.msg_queue.put(messages.ConnectionClose())

    def _on_error(self, ws, error):
        self.msg_queue.put(messages.ConnectionClose(error))

    def _on_message(self, ws, payload):
        self.msg_queue.put(messages.create_response(payload))

    def _wait_for_ws_connection(self, tm):
        self.logger.debug(
            "waiting_for_ws_connection {}".format(self.__dict__))
        if not self.process.assert_running():
            self.logger.info("CLI process is running")
        response = None
        start_time = time()
        while time() - start_time <= tm:
            try:
                response = self._wait_until(
                    self._is_connection_opened, tm - (time() - start_time))
                break
            except AdminApiTerminatedException as e:
                self.logger.info(str(e))
                self.process.restart(log_output=False)
        try:
            self._log_process_info()
        except Exception:
            pass

        if not self._is_connection_opened(response):
            self.logger.debug("_wait_for_ws_connection ")
            raise AdminApiConnectionClosedException(
                "Cannot establish socket connection. _wait_for_ws_connection")

    def _is_connection_opened(self, response):
        self.process.assert_running()
        return isinstance(response, messages.ConnectionOpen)

    def _wait_for_valid_response(self, request, validator, timeout):
        self.last_matching_response = None
        self._wait_until(lambda response: self._received_valid_resonse(
            response, request, validator), timeout)

        if not validator.check(self.last_matching_response.get_payload()):
            raise AdminApiProcedureTimeoutException("""Response for reqest ID {}, type {}: {}
            not received with valid parameters within timeout: {} seconds""".format(request.requestId,
                                                                                    request.requestType,
                                                                                    request.parameters,
                                                                                    timeout))

        return self.last_matching_response.get_payload()

    def _received_valid_resonse(self, response, request, validator):
        if isinstance(response, messages.ConnectionClose):
            self.logger.debug("ConnectionClose in _received_valid_resonse ")
            raise AdminApiConnectionClosedException(response)
        if not self._is_matching_api_response(response, request):
            return False
        if response.is_failure():
            raise AdminApiProcedureFailureException("""Response for reqest ID {}, type {}: {} recevied with error.
            Status reached: {}""".format(request.requestId, request.requestType, request.parameters, response.get_payload()))

        self.last_matching_response = response
        return validator.check(response.get_payload())

    def _wait_until_completed(self, request, timeout):
        """Wait until request is completed."""
        self.last_matching_response = None
        self._wait_until(lambda response: self._handle_response_and_check_if_final(
            response, request), timeout)

        if self.last_matching_response is not None:
            return self.last_matching_response
        raise AdminApiNoResponseException("""Response for reqest ID {}, type {}: {}
         not received within timeout: {} seconds""".format(request.requestId, request.requestType, request.parameters, timeout))

    def _get_all_updates_within_time(self, request, timeout):
        """Gets all the repsonses with requestStatus == update"""
        responses = []
        start_time = time()

        while time() - start_time <= timeout:
            response = self._get_last_response()
            if response:
                if isinstance(response, messages.ConnectionClose):
                    raise AdminApiConnectionClosedException(response)
                if self._is_matching_api_response(response, request):
                    if response.requestStatus == "update":
                        responses.append(response)

        if responses is not None:
            return responses
        raise AdminApiNoResponseException("""Response for reqest ID {}, type {}: {}
         not received within timeout: {} seconds""".format(request.requestId, request.requestType, request.parameters, timeout))

    def _handle_response_and_check_if_final(self, response, request):
        if isinstance(response, messages.ConnectionClose):
            self.logger.debug("ConnectionClose in _handle_response_and_check_if_final")
            raise AdminApiConnectionClosedException(response)

        if self._is_matching_api_response(response, request):
            self.last_matching_response = response
            return response.is_completed()

        return False

    def _send_message(self, msg):
        self.ws.send(msg.serialize())
        self.logger.debug("Send message: {}".format(msg))
        request_parameters = msg.get("parameters")
        self.message_flow_logger.debug("Sent message: {}".format(msg), extra={
            "api_request": {
                "request_id": msg.get("requestId"),
                "request_type": msg.get("requestType"),
                "name": request_parameters.get("name") if request_parameters is not None else None,
                "parameters": request_parameters.get("parameters") if request_parameters is not None else None
            }})

    def _is_matching_api_response(self, response, request):
        return isinstance(response, messages.AdminApiResponse) and response.get("requestStatus") and response.match(request)

    def _wait_until(self, is_ok, timeout=0):
        response = None
        start_time = time()
        while not is_ok(response) and time() - start_time <= timeout:
            response = self._get_last_response() or self.last_matching_response
        return response

    def _get_last_response(self):
        try:
            response = self.msg_queue.get(block=True, timeout=1)
        except queue.Empty:
            return None
        else:
            self.logger.debug("Received response: {}".format(response))
            try:
                self.message_flow_logger.debug("Received response: {}".format(response.get("requestMessage")), extra={
                    "api_response": {
                        "request_id": response.requestId,
                        "request_status": response.get("requestStatus"),
                        "request_message": response.get("requestMessage")
                    }})
            except AttributeError:
                pass
            return response

    def _get_cli_node_process_connections(self):
        node_connections = []
        try:
            process = psutil.Process(self.process.process.pid)
            all_connections = process.connections()
            parent_connections = process.parent().connections()
            for connection in all_connections:
                if connection not in parent_connections:
                    node_connections.append(connection)
        except Exception as e:
            self.process.logger.debug(str(e))

        return node_connections

    def _log_process_info(self):
        if self.process.remote_host:
            return
        try:
            self.process.logger.debug(
                "       Admin CLI cpu_percent: {}, cpu_times: {}".format(
                    psutil.Process(self.process.process.pid).cpu_percent(),
                    psutil.Process(self.process.process.pid).cpu_times()))
            self.process.logger.debug(
                "       Admin CLI memory_percent: {}, memory_info: {}".format(
                    psutil.Process(self.process.process.pid).memory_percent(),
                    psutil.Process(self.process.process.pid).memory_info()))
            self.process.logger.debug(
                "       Admin CLI process connections: {}".format(self._get_cli_node_process_connections()))
        except Exception as e:
            self.process.logger.debug(str(e))


def handle_file_io_v2(function):
    """Handle CLI 2.x.x file I/O"""
    @wraps(function)
    def _wrap(self, name, parameters, timeout, input_file_name=None, output_file_name=None, plan_scf_file=None,
              rat_scf_file=None, input_file_url=None):
        if input_file_name:
            self.input_size = os.stat(input_file_name).st_size
            self.input_file = open(input_file_name, "rb")
            parameters["inputFileContent"] = ""

        if output_file_name:
            ensure_parent_dir_exists(output_file_name)
            self.output_file = open(output_file_name, "wb")
            parameters["outputFileContent"] = ""

        if plan_scf_file:
            self.plan_scf_size = os.stat(plan_scf_file).st_size
            self.plan_scf_file = open(plan_scf_file, "rb")
            parameters["planScfFileContent"] = ""

        if rat_scf_file:
            self.rat_scf_size = os.stat(rat_scf_file).st_size
            self.rat_scf_file = open(rat_scf_file, "rb")
            parameters["ratScfFileContent"] = ""

        if input_file_url:
            self.input_size = check_url_and_get_file_size(input_file_url)
            self.input_file_url = input_file_url
            parameters["inputFileContent"] = ""

        try:
            return function(self, name, parameters, timeout)
        finally:
            self._close_input()
            self._close_output()
    return _wrap


def check_url_and_get_file_size(url):
    status_code = None
    try:
        file_info = requests.head(url)
        status_code = file_info.status_code
        is_partial_download_possible = file_info.headers["Accept-Ranges"] == 'bytes'
    except Exception as e:
        raise Exception("Unable to retrieve correct header from given URL: {}.\n"
                        "HTTP status code: {}\n"
                        "Please make sure that firewall rules which allows accessing URL are open."
                        "{}: {}".format(url, status_code, type(e).__name__, str(e)))

    if is_partial_download_possible:
        return file_info.headers["Content-Length"]
    else:
        raise Exception("Partial download is not supported within given URL: {}".format(url))


def _log_radar(request, username: str, host: str) -> None:
    request_parameters = request.get("parameters")
    log_radar(
        message="Sending Admin request",
        username=username,
        host=host,
        request_type=request.get("requestType"),
        name=request_parameters.get("name") if request_parameters is not None else None,
        parameters=request_parameters.get("parameters") if request_parameters is not None else None,
    )


class AdminApi_v2(AdminBaseApi):

    MAX_RETRY = 3

    def __init__(self, bts_host, bts_port, username, password, use_ssl, update_interval, debug_log, bundle_path,
                 remote_host, remote_host_username, remote_host_password, timeout, user_node_path):
        super().__init__(timeout)
        self.input_size = 0
        self.plan_scf_size = 0
        self.rat_scf_size = 0
        self.input_file = None
        self.plan_scf_file = None
        self.rat_scf_file = None
        self.output_file = None
        self.plan_size_sent = False
        self.plan_file_sent = False
        self.input_file_url = None
        self.session = None

        self.process = AdminApiProcessController_v2(
            bts_host, bts_port, username, password, use_ssl, update_interval, debug_log, bundle_path,
            remote_host, remote_host_username, remote_host_password, self.logger, user_node_path)

    @handle_file_io_v2
    def execute_infomodel_request(self, name, parameters, timeout, detailed_output=False):
        """Execute AdminAPI InfoModel request."""
        request = messages.AdminApiRequest_v2("infoModel", name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        return self.execute_request(request, timeout, detailed_output)

    @handle_file_io_v2
    def execute_procedure(self, name, parameters, timeout):
        """Execute AdminAPI procedure."""
        request = messages.AdminApiRequest_v2("procedure", name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        return self.execute_request(request, timeout)

    @handle_file_io_v2
    def execute_offline_procedure(self, name, parameters, timeout):
        """Execute AdminAPI offline procedure."""
        request = messages.AdminApiRequest_v2(
            "offlineProcedure", name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        return self.execute_request(request, timeout)

    @handle_file_io_v2
    def execute_customer_procedure(self, name, parameters, timeout):
        """Execute AdminAPI InfoModel request with empty type"""
        request = messages.AdminApiRequest_v2(None, name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        return self.execute_request(request, timeout, True)

    def execute_infomodel_subscription(self, name, parameters, validator, timeout):
        """Execute AdminAPI infomodel subscription."""
        request = messages.AdminApiRequest_v2("infoModel", name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        return self._execute_subscription(request, validator, timeout)

    def execute_procedure_subscription(self, name, parameters, validator, timeout):
        """Execute AdminAPI procedure result subscription."""
        request = messages.AdminApiRequest_v2("procedure", name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        return self._execute_subscription(request, validator, timeout)

    def execute_endless_procedure(self, name, parameters, timeout, finalizer_timeout, get_updates=False):
        """Execute AdminAPI endless procedure and finalize it after timeout."""
        request = messages.AdminApiRequest_v2("procedure", name, parameters)
        _log_radar(request, self.process.username, self.process.bts_host)
        self._send_message(request)
        if get_updates:
            response = self._get_all_updates_within_time(request, timeout)
        else:
            response = self._wait_until_completed(request, timeout)
        self.execute_procedure("requestsFinalizer", {
                               "requestId": request.requestId}, timeout=finalizer_timeout)
        return response

    def check_if_response_status_is_expected(self, response, expected_status):
        """Check if AdminAPI response status is expected."""
        if response.requestStatus == expected_status:
            return response
        else:
            raise AdminApiProcedureFailureException("""Response ID {} not received within expected status ({}).
            Status reached: {}""".format(response.requestId, expected_status, response.get_payload()))

    def _execute_subscription(self, original_request, validator, timeout):
        self.logger.debug('Original subscription request {} parameters: {}'.format(original_request.requestType,
                                                                                   original_request.parameters))
        trying_start_time = time()
        trying_stop_time = trying_start_time + timeout
        try_no = 1
        while time() < trying_stop_time:
            request = original_request
            request.requestId = randint(0, 100000)
            self.logger.debug('try no: {}\nrequest id: {}'.format(try_no, request.requestId))
            self._send_message(request)
            try:
                response = self._wait_for_valid_response(request, validator, timeout)
                self.execute_procedure("requestsFinalizer", {"requestId": request.requestId}, timeout=30)
                return response
            except Exception as e:
                self.logger.debug('Exception: {} occured while sending request:\n {} with parameters {}\n'.format(
                    str(e), request.requestType, request.parameters))
                try:
                    self.execute_procedure("requestsFinalizer", {"requestId": request.requestId}, timeout=30)
                except (AdminApiProcedureFailureException, AdminApiProcedureTimeoutException) as e:
                    self.logger.debug('Finalizing request {} ended up in exception: {}'.format(request.requestId, str(e)))
                    pass
                    try_no += 1
        raise AdminApiProcedureTimeoutException(""""Subscription request type {}: {}
                    not completed within timeout: {} sec""".format(original_request.requestType,
                                                                   original_request.parameters,
                                                                   timeout))

    def _handle_response_and_check_if_final(self, response, request):
        if (isinstance(response, messages.AdminFileTransferMessage) or
            isinstance(response, messages.AdminFileTransferPlanScfMessage) or
            isinstance(response, messages.AdminFileTransferRatScfMessage)) \
              and response.match(request):
                self._handle_file_transfer_message(response, request)
                return False

        return super()._handle_response_and_check_if_final(response, request)

    def _handle_file_transfer_message(self, msg, request):
        if msg.type == "CLOSE_WRITER":
            self._close_output()
        elif msg.type == "WRITE":
            self.output_file.write(base64.b64decode(msg.data))
        elif msg.type == "CLOSE_READER":
            self._close_input()
        elif msg.type == "SIZE":
            self._send_input_file_size(request)
        elif msg.type == "READ":
            self._send_input_file_chunk(request, msg.offset, msg.length)

    def _send_input_file_size(self, request):
        if self.input_size:
            self._send_message(messages.AdminFileTransferMessage(
                {"type": "SIZE", "id": request.requestId, "data": self.input_size}))
        elif self.plan_scf_size and not self.plan_size_sent:
            self._send_message(messages.AdminFileTransferPlanScfMessage(
                {"type": "SIZE", "id": request.requestId, "data": self.plan_scf_size}))
            self.plan_size_sent = True
        elif self.rat_scf_size and self.plan_size_sent:
            self._send_message(messages.AdminFileTransferRatScfMessage(
                {"type": "SIZE", "id": request.requestId, "data": self.rat_scf_size}))
            self.plan_size_sent = False

    def _send_input_file_chunk(self, request, offset, length):
        if self.input_file:
            self.input_file.seek(offset)
            payload = base64encode(self.input_file.read(length)).strip()
            self._send_message(messages.AdminFileTransferMessage(
                {"type": "READ", "id": request.requestId, "data": payload}))
        elif self.input_file_url:
            payload = base64encode(self._get_bytes_from_url(offset, length))
            self._send_message(messages.AdminFileTransferMessage(
                {"type": "READ", "id": request.requestId, "data": payload}))
        elif self.plan_scf_file and not self.plan_file_sent:
            self.plan_scf_file.seek(offset)
            payload = base64encode(self.plan_scf_file.read(length)).strip()
            self._send_message(messages.AdminFileTransferPlanScfMessage(
                {"type": "READ", "id": request.requestId, "data": payload}))
            self.plan_file_sent = True
        elif self.rat_scf_file and self.plan_file_sent:
            self.rat_scf_file.seek(offset)
            payload = base64encode(self.rat_scf_file.read(length)).strip()
            self._send_message(messages.AdminFileTransferRatScfMessage(
                {"type": "READ", "id": request.requestId, "data": payload}))
            self.plan_file_sent = False

    def _get_bytes_from_url(self, offset, length):
        if not self.session:
            self.session = requests.Session()

        header = {'Range': 'bytes={}-{}'.format(int(offset), int(offset) + int(length) - 1)}

        try_counter = 1

        # 5 seconds + 1 second for each 200KB in chunk
        timeout = 5 + int(length * 5 / (1024 * 1024))

        while try_counter <= self.MAX_RETRY:
            response = None
            try:
                response = self.session.get(self.input_file_url, headers=header, timeout=timeout)
            except Timeout as _:
                self.logger.debug(
                    'Gracefully handling connection or request timeout {} when downloading '
                    'chunk with offset: {} and length: {}'.format(timeout, offset, length)
                )
            except (ChunkedEncodingError, ConnectionError) as _:
                self.logger.debug(
                    'Gracefully handling network/server error when downloading '
                    'chunk with offset: {} and length: {}'.format(offset, length)
                )

            if response and response.status_code == 206:
                return response.content
            else:
                self.logger.debug(
                    'Attempt number {}/{} to fetch chunk with '
                    'offset: {} and length: {} failed.'.format(try_counter, self.MAX_RETRY, offset, length)
                )
                sleep(3)
                try_counter += 1

        raise Exception('Unable to get demanded bytes with offset: {} and length: {}.\n'
                        'Received http status code: {}.\n'.format(offset, length, 'Unknown' if not response else response.status_code))

    def _close_input(self):
        if self.input_file:
            self.input_file.close()
            self.input_file = None
        elif self.input_file_url:
            self.input_file_url = None
            self.session = None
        elif self.plan_scf_file:
            self.plan_scf_file.close()
            self.plan_scf_file = None
        elif self.rat_scf_file:
            self.rat_scf_file.close()
            self.rat_scf_file = None

    def _close_output(self):
        if self.output_file:
            self.output_file.close()
            self.output_file = None

    def look_for_open_node_process(self):
        """checks the num open connections and if there are more than one it gives an error message"""
        processes_number = get_node_process_counter(self.process.bts_host)
        self.logger.debug("node processes number: {}".format(str(processes_number)))
        if processes_number > 8:
            msg = "You are setting up a new cli process. \
You have already {} admin api processes running. BTS / SBTS will accept up to 10 \
consecutive connections. Above that limit you won't be able to connect by the library or by a browser.".\
                format(str(processes_number))
            self.logger.warning(msg)


class AdminApi:
    """This class is the entry for all Admin API's
       to be able to select at runtime the correct API version."""

    def __new__(cls, *args, **kwargs):
        timeout = args[-1]
        user_node_path = kwargs.get('user_node_path')

        api = AdminApi_v2(*args, user_node_path=user_node_path)  # pylint: disable-msg=E1120
        cls._setup_admin_api(api, timeout)

        return api

    @classmethod
    def _setup_admin_api(cls, api_instance, timeout):
        try:
            api_instance.setup()
            api_instance.execute_infomodel_request(
                "abnormalities", {"type": "currentAlarms"}, timeout)
        except Exception:
            api_instance.teardown()
            raise
